const alert = $('Webhook desde MS5 Alerts').first().json.body;
const aiBrief = $input.first().json?.emergencyParagraph || alert.recommendedAction;

const iconMap = {
  FROST_ALERT: '❄️🚨 ALERTA CRÍTICA DE HELADA EN SANDÍA',
  HEAT_AND_DROUGHT_SHOCK: '🔥💧 ALERTA CRÍTICA: GOLPE DE CALOR Y SEQUÍA RADICULAR',
  SUDDEN_NDVI_DROP: '🛰️🥀 ALERTA SATELITAL: CAÍDA BRUSCA DE VIGOR (NDVI)'
};

const header = iconMap[alert.ruleCode] || '🚨 ALERTA AGRONÓMICA AGROSAT AI';
const m = alert.metrics || {};

const message = `${header}\n\n` +
  `👨‍🌾 *Agricultor:* ${alert.farmer.fullName}\n` +
  `🍉 *Parcela:* ${alert.parcel.parcelAlias}\n` +
  `📍 *Ubicación:* \`${alert.parcel.centroid.lat}, ${alert.parcel.centroid.lon}\`\n\n` +
  `📊 *Indicadores Detectados:*\n` +
  (m.ambientTempC !== undefined ? `• 🌡️ Temp. Ambiente: *${m.ambientTempC} °C*\n` : '') +
  (m.soilMoisture20cmPct !== undefined ? `• 💧 Humedad Suelo (20cm): *${m.soilMoisture20cmPct}%*\n` : '') +
  (m.soilMoisture40cmPct !== undefined ? `• 💧 Humedad Suelo (40cm): *${m.soilMoisture40cmPct}%*\n` : '') +
  (m.currentNdvi !== undefined ? `• 🛰️ NDVI Sector Afectado: *${m.currentNdvi}* (Caída: -${m.ndviDrop})\n` : '') +
  `\n🧠 *Diagnóstico Rápido del Agrónomo Virtual (DeepSeek):*\n` +
  `_${aiBrief}_\n\n` +
  `⏱️ _Emitido: ${new Date(alert.triggeredAt).toLocaleString('es-MX')}_`;

return [{ json: { chatId: alert.farmer.telegramChatId, text: message } }];
